#include <Game/Demo/DemoTimeKeeper.hpp>
#include <cassert>
#include <cstring>
#include <cstdio>
class JMapInfo;
namespace DemoFunction {s32 createSheetParser(const DemoExecutor*,const char* sheet,JMapInfo** out){assert(!std::strcmp(sheet,"Time"));*out=nullptr;return 2;}}
namespace MR {void getCsvDataStrOrNULL(const char** out,const JMapInfo*,const char* key,s32 row){assert(!std::strcmp(key,"PartName"));*out=row?"Finish":"Intro";}void getCsvDataS32(s32* out,const JMapInfo*,const char* key,s32 row){if(!std::strcmp(key,"TotalStep"))*out=row?3:2;else{assert(!std::strcmp(key,"SuspendFlag"));*out=row?1:0;}}bool isEqualString(const char*a,const char*b){return a&&b&&!std::strcmp(a,b);}}
int main(){DemoTimeKeeper keeper(nullptr);assert(keeper.mNumPartInfos==2);assert(keeper.getPart("Intro")==0&&keeper.getPart("Finish")==1&&keeper.getPart("Missing")==-1);keeper.start();keeper.update();assert(keeper.mCurrentStep==0&&!keeper.isPartLast());keeper.update();assert(keeper.mCurrentStep==1&&keeper.isCurrentDemoPartLastStep());keeper.update();assert(keeper._18==1&&keeper.mCurrentStep==0&&keeper.isPartLast());keeper.update();assert(keeper.mCurrentStep==1);keeper.mIsPaused=true;auto elapsed=keeper._10;for(int i=0;i<100;++i)keeper.update();assert(keeper.mCurrentStep==1&&keeper._10==elapsed&&!keeper.isDemoEnd()&&!keeper.isPartLast());keeper.mIsPaused=false;keeper.update();assert(keeper.mCurrentStep==2&&keeper.isCurrentDemoPartLastStep()&&!keeper.isDemoEnd());keeper.update();assert(keeper.mCurrentStep==3&&keeper._18==1&&keeper.isExistSuspendFlagCurrentPart()&&keeper.isDemoEnd());keeper.setStartPart("Intro");assert(keeper._18==0&&keeper.mSubPartInfos==keeper.mMainPartInfos);keeper.end();assert(keeper.mCurrentStep==-1&&keeper._18==-1&&keeper._10==-1&&!keeper.mSubPartInfos);delete[] keeper.mMainPartInfos;std::puts("PASS original cutscene timeline: CSV-field fixture, part boundary, 100 paused updates, suspended-part completion, named selection and end reset");}
